    code: 'code', msedge: 'edge', microsoftedge: 'edge', 'ms-settings:': 'settings', 'ms-photos:': 'photos', control: 'settings', 'ncpa.cpl': 'settings', 'main.cpl': 'settings', 'appwiz.cpl': 'settings'
